import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.iXqqCa-C.js";const l="/images/agent-create-worldbook.webp",b=JSON.parse('{"title":"世界书","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/worldbook.md","filePath":"guide/agent/worldbook.md","lastUpdated":1793029602000}'),d={name:"guide/agent/worldbook.md"};function i(n,t,s,h,c,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="世界书" tabindex="-1">世界书 <a class="header-anchor" href="#世界书" aria-label="Permalink to &quot;世界书&quot;">​</a></h1><p>世界书是角色的<strong>背景知识库</strong>，存放世界观、地点、组织、人物关系、历史事件、专有名词等设定。条目<strong>按需注入</strong>：只有与当前对话相关的条目才会发送给模型。</p><p><img src="'+l+'" alt="世界书"></p><h2 id="条目字段" tabindex="-1">条目字段 <a class="header-anchor" href="#条目字段" aria-label="Permalink to &quot;条目字段&quot;">​</a></h2><p>每个条目包含：</p><ul><li><strong>标题</strong>：条目的名字。手动触发时用它（或条目 ID）。</li><li><strong>内容</strong>：具体的设定文字。</li><li><strong>关键词</strong>：触发该条目的词，用换行、英文逗号或中文逗号分隔。</li><li><strong>触发方式</strong>：见下。</li><li><strong>优先级</strong>：数值越大越优先注入。</li><li><strong>启用</strong>：开关，关闭后不参与注入。</li></ul><p>条目支持新增、复制、删除。</p><h2 id="三种触发方式" tabindex="-1">三种触发方式 <a class="header-anchor" href="#三种触发方式" aria-label="Permalink to &quot;三种触发方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>何时注入</th></tr></thead><tbody><tr><td>关键词</td><td>用户消息中出现关键词时。中文按包含关系匹配，英文按单词边界匹配</td></tr><tr><td>手动</td><td>消息里出现 <code>[[wb:条目标题]]</code> 或 <code>[[wb:条目ID]]</code> 时</td></tr><tr><td>常驻</td><td>每轮对话都参与注入</td></tr></tbody></table><h2 id="命中规则" tabindex="-1">命中规则 <a class="header-anchor" href="#命中规则" aria-label="Permalink to &quot;命中规则&quot;">​</a></h2><p>每轮对话最多注入 12 条：</p><ul><li>常驻最多 4 条</li><li>手动最多 4 条</li><li>关键词最多 8 条</li></ul><p>还有空位时，会按优先级从所有命中的条目里补齐。</p><h2 id="命中预览" tabindex="-1">命中预览 <a class="header-anchor" href="#命中预览" aria-label="Permalink to &quot;命中预览&quot;">​</a></h2><p>编辑页提供「命中预览」：输入一段测试消息，可以看到本轮实际会注入哪些条目（含触发来源、优先级、命中的关键词）。</p><p>手动条目在预览旁有一键插入按钮，可以快速把 <code>[[wb:标题]]</code> 标记插进消息。</p><h2 id="与记忆的分工" tabindex="-1">与记忆的分工 <a class="header-anchor" href="#与记忆的分工" aria-label="Permalink to &quot;与记忆的分工&quot;">​</a></h2><p>世界书由创作者编写，对所有用户相同；<a href="/guide/agent/memory">记忆</a>按会话独立，记录每个用户自己的对话内容。</p>',18)])])}const u=a(d,[["render",i]]);export{b as __pageData,u as default};
